use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut prev_q = false
        for c in line.chars() {
            if inq {
                if c == '"' {
                    inq = false
                    prev_q = true
                } else {
                    cur = cur + &c.to_string()
                }
            } else if c == '"' {
                inq = true
                if prev_q {
                    cur = cur + "\""
                }
                prev_q = false
            } else if c == ',' {
                fields.push(cur)
                cur = ""
                prev_q = false
            } else if c != '\r' {
                cur = cur + &c.to_string()
                prev_q = false
            }
        }
        fields.push(cur)
        let mut out = ""
        let mut i = 0
        for f in fields {
            if i > 0 { out = out + "|" }
            out = out + "[" + f + "]"
            i += 1
        }
        println("${i}: ${out}")
    }
}

